        }
    }

    // Base: connect k-1 -> k with 0 and 2^(k-2), giving [0, 2^(k-1)-1] at vertex k
    edges[m++] = (Edge){k - 1, k, 0};
    edges[m++] = (Edge){k - 1, k, (int)(1LL << (k - 2))};

